window.MHA_ACT = {"meta":{"act":"Mental Health Act 2007 (NSW) No 8","currency":"in force 28 March 2026","lastConsolidatedAmendment":"Act No 61 of 2025","retrieved":"31 August 2026","source":"NSW Parliamentary Counsel consolidated XML (legislation.nsw.gov.au)","url":"https://legislation.nsw.gov.au/view/html/inforce/current/act-2007-008"},"sections":[{"n":"3","heading":"Objects of Act","lines":[[0,"The objects of this Act are—"],[1,"(a) to provide for the care and treatment of, and to promote the recovery of, persons who are mentally ill or mentally disordered, and"],[1,"(b) to facilitate the care and treatment of those persons through community care facilities, and"],[1,"(c) to facilitate the provision of hospital care for those persons on a voluntary basis where appropriate and, in a limited number of situations, on an involuntary basis, and"],[1,"(d) while protecting the civil rights of those persons, to give an opportunity for those persons to have access to appropriate care and, where necessary, to provide for treatment for their own protection or the protection of others, and"],[1,"(e) to facilitate the involvement of those persons, and persons caring for them, in decisions involving appropriate care and treatment."],[0,"Note: Note. See also section 68 which contains principles for care and treatment and section 105 which sets out objectives for the New South Wales public health system."]],"url":"https://legislation.nsw.gov.au/view/html/inforce/current/act-2007-008#/sec.3"},{"n":"4","heading":"Definitions","lines":[[1,"(1) In this Act—"],[2,"accredited person means a person accredited under section 136."],[2,"ambulance officer means a member of staff of the NSW Health Service who is authorised by the Secretary to exercise functions of an ambulance officer under this Act."],[2,"assessable person—see section 17."],[2,"authorised medical officer of a mental health facility means—"],[3,"(a) the medical superintendent of the mental health facility, or"],[3,"(b) a medical officer, nominated by the medical superintendent for the purposes of this Act, attached to the mental health facility concerned."],[2,"community treatment order means a community treatment order in force under Part 3 of Chapter 3."],[2,"correctional patient has the same meaning as it has in the Mental Health and Cognitive Impairment Forensic Provisions Act 2020."],[2,"Court means the Supreme Court."],[2,"declared mental health facility means premises subject to an order in force under section 109."],[2,"Deputy President means a person appointed as a Deputy President of the Tribunal."],[2,"designated carer—see section 71."],[2,"determination of the Tribunal includes an order, direction or decision of the Tribunal."],[2,"director of community treatment—see section 50."],[2,"exercise a function includes perform a duty."],[2,"forensic patient has the same meaning as it has in the Mental Health and Cognitive Impairment Forensic Provisions Act 2020."],[2,"function includes a power, authority or duty."],[2,"guardian, in relation to the exercise of any function under this Act by the guardian of a person under guardianship, means a guardian who is able to exercise that function."],[2,"involuntary patient means—"],[3,"(a) a person who is ordered to be detained as an involuntary patient after a mental health inquiry or otherwise by the Tribunal, or"],[3,"(b) a forensic patient who is re-classified as an involuntary patient under the Mental Health and Cognitive Impairment Forensic Provisions Act 2020, or"],[3,"(c) a correctional patient who is re-classified as an involuntary patient under the Mental Health and Cognitive Impairment Forensic Provisions Act 2020."],[2,"medical superintendent—"],[3,"(a) of a declared mental health facility, means the medical practitioner appointed, under section 111, as medical superintendent of the facility, or"],[3,"(b) of a private mental health facility, means the medical practitioner appointed, under section 124, as medical superintendent of the facility."],[2,"mental health certificate—see section 17."],[2,"mental health facility means a declared mental health facility or a private mental health facility."],[2,"mental health inquiry means an inquiry conducted by the Tribunal under Division 3 of Part 2 of Chapter 3."],[2,"mental illness means a condition that seriously impairs, either temporarily or permanently, the mental functioning of a person and is characterised by the presence in the person of any one or more of the following symptoms—"],[3,"(a) delusions,"],[3,"(b) hallucinations,"],[3,"(c) serious disorder of thought form,"],[3,"(d) a severe disturbance of mood,"],[3,"(e) sustained or repeated irrational behaviour indicating the presence of any one or more of the symptoms referred to in paragraphs (a)–(d)."],[2,"mentally disordered person—see section 15."],[2,"mentally ill person—see section 14."],[2,"parent, of a child, means any person having parental responsibility (within the meaning of the Children and Young Persons (Care and Protection) Act 1998) for the child."],[2,"patient means a person who is admitted to a mental health facility in accordance with this Act and who is in the facility following the person’s admission, and includes a person so admitted while absent from the facility either with or without leave of absence."],[2,"person under guardianship means a person under guardianship within the meaning of the Guardianship Act 1987."],[2,"premises includes any land, building and part of any building."],[2,"President means the President of the Tribunal."],[2,"principal care provider—see section 72A."],[2,"private mental health facility means premises subject to a licence under Division 2 of Part 2 of Chapter 5."],[2,"Secretary means the Secretary of the Ministry of Health."],[2,"spouse means—"],[3,"(a) the person to whom a person is legally married (including the husband or wife of a person), or"],[3,"(b) a de facto partner,"],[2,"but where more than one person would qualify as a spouse, means only the last person to so qualify."],[2,"Note: Note. “De facto partner” is defined in section 21C of the Interpretation Act 1987."],[2,"surgical operation—see section 98."],[2,"Tribunal means the Mental Health Review Tribunal constituted under Chapter 6."],[2,"voluntary patient means—"],[3,"(a) a person who has been admitted to a mental health facility under Chapter 2, or"],[3,"(b) a person who has been re-classified as a voluntary patient under this Act."],[1,"Note: Note. The Interpretation Act 1987 contains definitions and other provisions that affect the interpretation and application of this Act."],[1,"(2) Notes included in this Act (other than in Schedule 1) do not form part of this Act."]],"url":"https://legislation.nsw.gov.au/view/html/inforce/current/act-2007-008#/sec.4"},{"n":"5","heading":"Admission on own request","lines":[[1,"(1) A person may be admitted to a mental health facility as a voluntary patient."],[1,"(2) An authorised medical officer may refuse to admit a person to a mental health facility as a voluntary patient if the officer is not satisfied that the person is likely to benefit from care or treatment as a voluntary patient."],[1,"(3) A person may be admitted to a mental health facility as a voluntary patient whether or not the person is a mentally ill person or a mentally disordered person."]],"url":"https://legislation.nsw.gov.au/view/html/inforce/current/act-2007-008#/sec.5"},{"n":"8","heading":"Discharge of voluntary patients","lines":[[1,"(1) An authorised medical officer may discharge a voluntary patient at any time if the officer is of the opinion that the patient is not likely to benefit from further care or treatment as a voluntary patient."],[1,"(2) A voluntary patient may discharge himself or herself from or leave a mental health facility at any time."],[1,"(3) An authorised medical officer must give notice of the discharge of a voluntary patient who is a person under guardianship to the person’s guardian."],[0,"Note: Note. Section 79 provides for appropriate information relating to follow-up care to be provided to patients being discharged."]],"url":"https://legislation.nsw.gov.au/view/html/inforce/current/act-2007-008#/sec.8"},{"n":"9","heading":"Review of voluntary patients","lines":[[1,"(1) The Tribunal must review, at least once every 12 months, the case of each voluntary patient who has been receiving care or treatment, or both, whether in a voluntary or involuntary capacity in a mental health facility for a continuous period of more than 12 months."],[1,"(2) In addition to any other matters it considers on a review, the Tribunal is to consider whether the patient consents to continue as a voluntary patient and whether the patient is likely to benefit from further care or treatment as a voluntary patient."],[1,"(3) The Tribunal may on a review order the discharge of the patient from the mental health facility."],[1,"(4) The Tribunal may defer the operation of an order for the discharge of a patient for a period of up to 14 days, if the Tribunal thinks it is in the best interests of the patient to do so."],[1,"(5) The medical superintendent of a mental health facility must notify the Tribunal of the name of any voluntary patient whose case the Tribunal is required to review."]],"url":"https://legislation.nsw.gov.au/view/html/inforce/current/act-2007-008#/sec.9"},{"n":"10","heading":"Detention of voluntary patients in mental health facilities","lines":[[1,"(1) An authorised medical officer may cause a voluntary patient to be detained in a mental health facility under Part 2 of Chapter 3 if the officer considers the person to be a mentally ill person or a mentally disordered person."],[1,"(2) Any such patient is taken to have been detained in the facility under section 19 when the authorised medical officer takes action to detain the patient."],[1,"(3) A voluntary patient in a mental health facility may be detained for a period of up to 2 hours for the purpose of enabling an authorised medical officer to exercise the officer’s functions under this section."]],"url":"https://legislation.nsw.gov.au/view/html/inforce/current/act-2007-008#/sec.10"},{"n":"12","heading":"General restrictions on detention of persons","lines":[[1,"(1) A patient or other person must not be involuntarily admitted to, or detained in or continue to be detained in, a mental health facility unless an authorised medical officer is of the opinion that—"],[2,"(a) the person is a mentally ill person or a mentally disordered person, and"],[2,"(b) no other care of a less restrictive kind, that is consistent with safe and effective care, is appropriate and reasonably available to the person."],[1,"(2) If an authorised medical officer is not of that opinion about a patient or other person at a mental health facility, the officer must refuse to detain, and must not continue to detain, the person."],[1,"(3) An authorised medical officer may, immediately on discharging a patient or person who has been detained in a mental health facility, admit that person as a voluntary patient."]],"url":"https://legislation.nsw.gov.au/view/html/inforce/current/act-2007-008#/sec.12"},{"n":"13","heading":"Criteria for involuntary admission etc as mentally ill person or mentally disordered person","lines":[[0,"A person is a mentally ill person or a mentally disordered person for the purpose of—"],[1,"(a) the involuntary admission of the person to a mental health facility or the detention of the person in a facility under this Act, or"],[1,"(b) determining whether the person should be subject to a community treatment order or be detained or continue to be detained involuntarily in a mental health facility,"],[0,"if, and only if, the person satisfies the relevant criteria set out in this Part."]],"url":"https://legislation.nsw.gov.au/view/html/inforce/current/act-2007-008#/sec.13"},{"n":"14","heading":"Mentally ill persons","lines":[[1,"(1) A person is a mentally ill person if the person is suffering from mental illness and, owing to that illness, there are reasonable grounds for believing that care, treatment or control of the person is necessary—"],[2,"(a) for the person’s own protection from serious harm, or"],[2,"(b) for the protection of others from serious harm."],[1,"(2) In considering whether a person is a mentally ill person, the continuing condition of the person, including any likely deterioration in the person’s condition and the likely effects of any such deterioration, are to be taken into account."]],"url":"https://legislation.nsw.gov.au/view/html/inforce/current/act-2007-008#/sec.14"},{"n":"15","heading":"Mentally disordered persons","lines":[[0,"A person (whether or not the person is suffering from mental illness) is a mentally disordered person if the person’s behaviour for the time being is so irrational as to justify a conclusion on reasonable grounds that temporary care, treatment or control of the person is necessary—"],[1,"(a) for the person’s own protection from serious physical harm, or"],[1,"(b) for the protection of others from serious physical harm."]],"url":"https://legislation.nsw.gov.au/view/html/inforce/current/act-2007-008#/sec.15"},{"n":"16","heading":"Certain words or conduct may not indicate mental illness or disorder","lines":[[1,"(1) A person is not a mentally ill person or a mentally disordered person merely because of any one or more of the following—"],[2,"(a) the person expresses or refuses or fails to express or has expressed or refused or failed to express a particular political opinion or belief,"],[2,"(b) the person expresses or refuses or fails to express or has expressed or refused or failed to express a particular religious opinion or belief,"],[2,"(c) the person expresses or refuses or fails to express or has expressed or refused or failed to express a particular philosophy,"],[2,"(d) the person expresses or refuses or fails to express or has expressed or refused or failed to express a particular sexual preference or sexual orientation,"],[2,"(d1) the person expresses or refuses or fails to express or has expressed or refused or failed to express a particular gender identity or gender expression,"],[2,"(e) the person engages in or refuses or fails to engage in, or has engaged in or refused or failed to engage in, a particular political activity,"],[2,"(f) the person engages in or refuses or fails to engage in, or has engaged in or refused or failed to engage in, a particular religious activity,"],[2,"(g) the person engages in or has engaged in a particular sexual activity or sexual promiscuity,"],[2,"(h) the person engages in or has engaged in immoral conduct,"],[2,"(i) the person engages in or has engaged in illegal conduct,"],[2,"(j) the person has an intellectual disability or developmental disability,"],[2,"(k) the person takes or has taken alcohol or any other drug,"],[2,"(l) the person engages in or has engaged in anti-social behaviour,"],[2,"(m) the person has a particular economic or social status or is a member of a particular cultural or racial group."],[1,"(2) Nothing in this Part prevents, in relation to a person who takes or has taken alcohol or any other drug, the serious or permanent physiological, biochemical or psychological effects of drug taking from being regarded as an indication that a person is suffering from mental illness or other condition of disability of mind."]],"url":"https://legislation.nsw.gov.au/view/html/inforce/current/act-2007-008#/sec.16"},{"n":"17","heading":"Definitions","lines":[[0,"In this Part—"],[1,"assessable person means a person detained in a declared mental health facility for whom a mental health inquiry is required to be held under this Part."],[1,"mental health certificate means a certificate given under section 19."]],"url":"https://legislation.nsw.gov.au/view/html/inforce/current/act-2007-008#/sec.17"},{"n":"18","heading":"When a person may be detained in mental health facility","lines":[[1,"(1) A person may be detained in a declared mental health facility in the following circumstances—"],[2,"(a) on a mental health certificate given by a medical practitioner or accredited person (see section 19),"],[2,"(b) after being brought to the facility by an ambulance officer (see section 20),"],[2,"(c) after being apprehended by a police officer (see section 22),"],[2,"(d) after an order for an examination and an examination or observation by a medical practitioner or accredited person (see section 23),"],[2,"(e) on the order of a Judge of the Local Court (see section 24),"],[2,"(f) after a transfer from another health facility (see section 25),"],[2,"(g) on a written request made to the authorised medical officer by a designated carer, the principal care provider, a relative or friend of the person (see section 26)."],[1,"(2) A person may be detained, under a provision of this Part, in a health facility that is not a declared mental health facility if it is necessary to do so to provide medical treatment or care to the person for a condition or illness other than a mental illness or other mental condition."],[1,"(3) In this Act, a reference to taking to and detaining in a mental health facility includes, in relation to a person who is at a mental health facility, but not detained in the mental health facility in accordance with this Act, the detaining of the person in the mental health facility."],[0,"Note: Note 1— A person taken to and detained in a mental health facility must be provided with certain information, including a statement of the person’s rights (see section 74)."],[0,"Note: Note 2— A person authorised to be taken to and detained in a mental health facility under this Division may be taken to the facility by a person listed in section 81."]],"url":"https://legislation.nsw.gov.au/view/html/inforce/current/act-2007-008#/sec.18"},{"n":"19","heading":"Detention on certificate of medical practitioner or accredited person","lines":[[1,"(1) A person may be taken to and detained in a declared mental health facility on the basis of a certificate about the person’s condition issued by a medical practitioner or accredited person. The certificate is to be in the form set out in Part 1 of Schedule 1."],[1,"(2) A mental health certificate may be given about a person only if the medical practitioner or accredited person—"],[2,"(a) has personally examined or observed the person’s condition immediately before or shortly before completing the certificate, and"],[2,"(b) is of the opinion that the person is a mentally ill person or a mentally disordered person, and"],[2,"(c) is satisfied that no other appropriate means for dealing with the person is reasonably available, and that involuntary admission and detention are necessary, and"],[2,"(d) is not a designated carer, the principal care provider or a near relative of the person."],[1,"(3) A mental health certificate may contain a police assistance endorsement that police assistance is required if the person giving the certificate is of the opinion that there are serious concerns relating to the safety of the person or other persons if the person is taken to a mental health facility without the assistance of a police officer. The endorsement is to be in the form set out in Part 2 of Schedule 1."],[1,"(4) A mental health certificate may not be used to admit or detain a person in a facility—"],[2,"(a) in the case of a person certified to be a mentally ill person, more than 5 days after it is given, or"],[2,"(b) in the case of a person certified to be a mentally disordered person, more than one day after it is given."],[1,"(5) In this section—"],[2,"near relative of a person means a parent, brother, sister, child or spouse of the person and any other person prescribed for the purposes of this definition."]],"url":"https://legislation.nsw.gov.au/view/html/inforce/current/act-2007-008#/sec.19"},{"n":"19A","heading":"Examination by audio visual link for purposes of mental health certificate","lines":[[1,"(1) A medical practitioner or accredited person may examine or observe a person’s condition using an audio visual link for the purpose of determining whether to issue a mental health certificate if it is not reasonably practicable for a medical practitioner or accredited person to personally examine or observe the person for that purpose."],[1,"(2) A medical practitioner or accredited person must not carry out an examination or observation using an audio visual link unless the medical practitioner or accredited person is satisfied that the examination or observation can be carried out in those circumstances with sufficient skill and care so as to form the required opinion about the person."],[1,"(3) The regulations may make provision for or with respect to the audio visual link technology that may be used for the purposes of this section and the medical practitioners who may examine or observe a person for the purposes of this section."]],"url":"https://legislation.nsw.gov.au/view/html/inforce/current/act-2007-008#/sec.19a"},{"n":"20","heading":"Detention on information of ambulance officer","lines":[[1,"(1) An ambulance officer who provides ambulance services in relation to a person may take the person to a declared mental health facility if the officer believes on reasonable grounds that the person appears to be mentally ill or mentally disturbed and that it would be beneficial to the person’s welfare to be dealt with in accordance with this Act."],[1,"(2) An ambulance officer may request police assistance if of the opinion that there are serious concerns relating to the safety of the person or other persons if the person is taken to a mental health facility without the assistance of a police officer."]],"url":"https://legislation.nsw.gov.au/view/html/inforce/current/act-2007-008#/sec.20"},{"n":"21","heading":"Police assistance","lines":[[1,"(1) A police officer to whose notice a police assistance endorsement on a mental health certificate, or a request for assistance by an ambulance officer under this Division, is brought must, if practicable—"],[2,"(a) apprehend and take or assist in taking the person the subject of the certificate or request to a declared mental health facility, or"],[2,"(b) cause or make arrangements for some other police officer to do so."],[1,"(2) A police officer may enter premises to apprehend a person under this section, and may apprehend any such person, without a warrant and may exercise any powers conferred by section 81 on a person who is authorised under that section to take a person to a mental health facility or another health facility."],[1,"Note: Note. Section 81 sets out the persons who may take a person to a mental health facility and their powers when doing so."]],"url":"https://legislation.nsw.gov.au/view/html/inforce/current/act-2007-008#/sec.21"},{"n":"22","heading":"Detention after apprehension by police","lines":[[1,"(1) A police officer who, in any place, finds a person who appears to be mentally ill or mentally disturbed may apprehend the person and take the person to a declared mental health facility if the officer believes on reasonable grounds that—"],[2,"(a) the person is committing or has recently committed an offence or that the person has recently attempted to kill himself or herself or that it is probable that the person will attempt to kill himself or herself or any other person or attempt to cause serious physical harm to himself or herself or any other person, and"],[2,"(b) it would be beneficial to the person’s welfare to be dealt with in accordance with this Act, rather than otherwise in accordance with law."],[1,"(2) A police officer may apprehend a person under this section without a warrant and may exercise any powers conferred by section 81 on a person who is authorised under that section to take a person to a mental health facility or another health facility."]],"url":"https://legislation.nsw.gov.au/view/html/inforce/current/act-2007-008#/sec.22"},{"n":"23","heading":"Detention after order for medical examination or observation","lines":[[1,"(1) A Judge of the Local Court or authorised officer may, by order, authorise a medical practitioner or accredited person to visit and to personally examine or personally observe a person to ascertain whether a mental health certificate should be issued for the person."],[1,"(2) An order may be made if the judge or officer is satisfied, by evidence on oath, that—"],[2,"(a) the person may be a mentally ill person or a mentally disordered person, and"],[2,"(b) because of physical inaccessibility, the person could not otherwise be personally examined or personally observed."],[1,"(3) The order may also authorise any other person (including a police officer) who may be required to assist the medical practitioner or accredited person to accompany the medical practitioner or accredited person."],[1,"(4) A person authorised to visit a person or accompany another person may enter premises, if need be by force, in order to enable the examination or observation to be carried out."],[1,"(5) A person who is examined or observed under this section may be detained in accordance with section 19."],[1,"(6) A person who takes action under an order must, as soon as practicable after taking the action, notify the person who made the order in writing of the action."],[1,"(7) In this section—"],[2,"authorised officer means an authorised officer within the meaning of the Criminal Procedure Act 1986."]],"url":"https://legislation.nsw.gov.au/view/html/inforce/current/act-2007-008#/sec.23"},{"n":"24","heading":"Detention on order of Judge","lines":[[0,"A person may be taken to and detained in a declared mental health facility in accordance with an order made under Division 3 of Part 2 of the Mental Health and Cognitive Impairment Forensic Provisions Act 2020."]],"url":"https://legislation.nsw.gov.au/view/html/inforce/current/act-2007-008#/sec.24"},{"n":"25","heading":"Detention after transfer from another health facility","lines":[[1,"(1) A person may be transferred from a health facility to a declared mental health facility and detained in the mental health facility if a medical officer of the health facility, or the authorised medical officer of the mental health facility, considers the person to be a mentally ill person or a mentally disordered person."],[1,"(2) Any such person is taken to have been detained in the declared mental health facility under section 19 when the person is transferred to the facility."]],"url":"https://legislation.nsw.gov.au/view/html/inforce/current/act-2007-008#/sec.25"},{"n":"26","heading":"Detention on request of designated carer, principal care provider, relative or friend","lines":[[1,"(1) A person may be detained in a declared mental health facility on a written request made to the authorised medical officer by a designated carer, the principal care provider or a relative or friend of the person."],[1,"(2) An authorised medical officer must not detain any such person unless the officer is satisfied that, because of the distance required in order for the person to be examined and the urgency of the circumstances, it is not reasonably practicable to have the person detained on the basis of a mental health certificate."]],"url":"https://legislation.nsw.gov.au/view/html/inforce/current/act-2007-008#/sec.26"},{"n":"27","heading":"Steps for medical examination requirements for ongoing detention in mental health facility","lines":[[1,"(1) The following steps must be taken in relation to a person who is detained in a mental health facility under this Division—"],[2,"(a) An authorised medical officer must examine the person as soon as practicable (but not later than 12 hours) after the person arrives at the facility or after the person is detained after being a voluntary patient."],[2,"The person must not be detained after the examination unless the officer certifies that, in the officer’s opinion, the person is a mentally ill person or a mentally disordered person."],[2,"(b) The authorised medical officer must cause the person to be examined by another medical practitioner as soon as possible after giving the certificate in step 1. The second examiner must be a psychiatrist if the authorised medical officer is not a psychiatrist."],[2,"The second examiner must notify the authorised medical officer if of the opinion that the person is a mentally ill person or a mentally disordered person or if not able to form such an opinion."],[2,"(c) If the second examiner is not of the opinion that the person is a mentally ill person or a mentally disordered person, the authorised medical officer must cause the person to be examined by a medical practitioner who is a psychiatrist, as soon as practicable after being notified of that opinion."],[2,"The third examiner must notify the authorised medical officer if of the opinion that the person is a mentally ill person or a mentally disordered person."],[2,"(d) An authorised medical officer must notify the Tribunal and bring the person before the Tribunal for a mental health inquiry if—"],[3,"(i) the person is found to be a mentally ill person by an authorised medical officer on initial examination in step 1, and to be a mentally ill person or a mentally disordered person on examination in step 2 or step 3, or"],[3,"(ii) the person is found to be a mentally disordered person by an authorised medical officer on initial examination in step 1, and to be a mentally ill person on examination in step 2 or step 3."],[2,"The person must be brought before the Tribunal as soon as practicable after admission (subject to meeting the requirements set out above)."],[2,"If the third examiner does not find that the person is a mentally ill person or a mentally disordered person, the person must not be detained after the third examination."],[2,"(e) If a person is found to be a mentally disordered person by an authorised medical officer on initial examination in step 1, and is found to be a mentally disordered person on examination in step 2 or step 3, the person may be detained in the mental health facility as a mentally disordered person."],[1,"(2) Any certification under subsection (1) (a) or notification under subsection (1) (b) or (c) of the opinion that a person is, after an examination under this section or section 27A, a mentally ill person or a mentally disordered person, is to be in the form prescribed by the regulations."],[1,"(3) Any form used for the purposes of this section or section 27A (as in force immediately before the commencement of this subsection) is, until such time as a form is prescribed for the purposes of subsection (2), taken to be the form so prescribed."]],"url":"https://legislation.nsw.gov.au/view/html/inforce/current/act-2007-008#/sec.27"},{"n":"27A","heading":"Examinations by medical practitioners or accredited persons for purposes of detention","lines":[[1,"(1) If it is not reasonably practicable for an authorised medical officer of a mental health facility or other medical practitioner to personally examine a person or observe the person’s condition for the purpose of determining under section 27 whether the person is a mentally ill person or a mentally disordered person, the person may be examined or observed for that purpose—"],[2,"(a) by a medical practitioner using an audio visual link, or"],[2,"(b) by an accredited person authorised by the medical superintendent of the mental health facility to examine or observe the person or observe for that purpose—"],[3,"(i) in person, or"],[3,"(ii) using an audio visual link."],[1,"(2) The examination or observation must be carried out by a medical practitioner who is a psychiatrist if that is a requirement of section 27."],[1,"(3) A medical practitioner or accredited person must not carry out an examination or observation using an audio visual link under this section unless the medical practitioner or accredited person is satisfied that the examination or observation can be carried out in the circumstances with sufficient skill and care so as to form the required opinion about the person."],[1,"(4) A medical practitioner who is not a psychiatrist, or an accredited person, who examines or observes a person under this section must, if it is reasonably practicable to do so, seek the advice of a psychiatrist before making a determination as to whether the person is a mentally ill person or a mentally disordered person. The psychiatrist is not required to examine or observe the person."],[1,"(5) The regulations may make provision for or with respect to the audio visual link technology that may be used for the purposes of this section and the medical practitioners who may examine or observe a person for the purposes of this section."]],"url":"https://legislation.nsw.gov.au/view/html/inforce/current/act-2007-008#/sec.27a"},{"n":"28","heading":"Obligations of examining medical practitioners and accredited persons","lines":[[1,"(1) An authorised medical officer or other medical practitioner or accredited person who examines a person detained in a mental health facility under this Division may take into account his or her own observations and any other available evidence that he or she considers reliable and relevant in forming an opinion as to whether the person is a mentally ill person or a mentally disordered person."],[1,"(2) A medical practitioner or accredited person on whose certificate or request a person has been admitted to a mental health facility must not examine the person under section 27 or 27A."]],"url":"https://legislation.nsw.gov.au/view/html/inforce/current/act-2007-008#/sec.28"},{"n":"29","heading":"Treatment of persons detained in mental health facilities","lines":[[0,"A person who authorises the administration of any medication to a person detained in a mental health facility under this Division—"],[1,"(a) must have due regard to the possible effects of the administration of the medication, and"],[1,"(b) must prescribe the minimum medication, consistent with proper care, to ensure that the person is not prevented from communicating adequately with any other person who may be engaged to represent the person at a mental health inquiry."]],"url":"https://legislation.nsw.gov.au/view/html/inforce/current/act-2007-008#/sec.29"},{"n":"30","heading":"Assessable persons may be reclassified as voluntary patients","lines":[[0,"An authorised medical officer may classify an assessable person as a voluntary patient at any time before a mental health inquiry is held about the person, but only if—"],[1,"(a) the authorised medical officer is of the opinion that the person is likely to benefit from care or treatment as a voluntary patient, and"],[1,"(b) the patient agrees to be so classified or, if the person is a person under guardianship or is under the age of 14 years, the person is admitted in accordance with the procedures under this Act applicable to admitting any such person as a voluntary patient."]],"url":"https://legislation.nsw.gov.au/view/html/inforce/current/act-2007-008#/sec.30"},{"n":"31","heading":"Limited detention of mentally disordered persons","lines":[[1,"(1) A person detained as a mentally disordered person under step 5 in section 27 (e) must not be detained in a mental health facility for a continuous period of more than 3 days (not including weekends and public holidays)."],[1,"(2) If an authorised medical officer of a mental health facility is of the opinion that an assessable person has ceased to be a mentally ill person but is a mentally disordered person, the person must not be further detained in the facility for a continuous period of more than 3 days (not including weekends and public holidays)."],[1,"(3) An authorised medical officer must examine a mentally disordered person detained in a mental health facility at least once every 24 hours."],[1,"(4) The person must not be further detained in the mental health facility if, on any such examination, the authorised medical officer is of the opinion that the person is not a mentally disordered person or a mentally ill person or that other care of a less restrictive kind, that is consistent with safe and effective care, is appropriate and reasonably available to the person."],[1,"(5) A person must not be admitted to and detained in a mental health facility on the grounds that the person is a mentally disordered person on more than 3 occasions in any 1 calendar month."]],"url":"https://legislation.nsw.gov.au/view/html/inforce/current/act-2007-008#/sec.31"},{"n":"33","heading":"Actions may be delayed because of other illnesses or conditions","lines":[[0,"Despite any other provision of this Act, an authorised medical officer is not required—"],[1,"(a) to take or complete a step referred to in section 27, or"],[1,"(b) to bring a person before the Tribunal for a mental health inquiry,"],[0,"while the person is suffering from a condition or illness other than a mental illness or other mental condition and is not, in the officer’s opinion, fit to be the subject of the proposed action due to the seriousness of the person’s condition or illness."]],"url":"https://legislation.nsw.gov.au/view/html/inforce/current/act-2007-008#/sec.33"},{"n":"34","heading":"Mental health inquiries to be held","lines":[[1,"(1) The Tribunal must hold an inquiry about an assessable person under step 4 in section 27 (d)."],[1,"Note: Note. Section 27 sets out the events that result in a mental health inquiry. Notice of the inquiry is to be given to the person concerned, and all reasonably practicable steps are to be taken to notify designated carers and the principal care provider in accordance with section 76."],[1,"(2) An authorised medical officer of the mental health facility in which an assessable person is detained—"],[2,"(a) must ensure that, as far as practicable, the person is brought before the Tribunal dressed in street clothes, and"],[2,"(b) must make all necessary arrangements to ensure that all appropriate medical witnesses appear before the Tribunal and other relevant medical evidence concerning the person is placed before the Tribunal at or before the inquiry, and"],[2,"(c) as soon as practicable after notifying the Tribunal under section 27 (d), and at or before the inquiry, must provide the Tribunal with all relevant medical reports of the examinations in step 1 or step 2, as referred to in section 27 (d), and any additional information required by the Tribunal for the purposes of the inquiry."],[1,"An assessable person, or any other person, may, with the approval of the Tribunal and subject to the regulations (if any), be brought or appear before the Tribunal by way of audio visual link."],[1,"Any designated carer or the principal care provider of an assessable person may, with the approval of the Tribunal, appear at an inquiry."],[1,"Note: Note. The Tribunal must be constituted by at least one member who is the President or a Deputy President for the purposes of a mental health inquiry (see section 150 (2A)). Other provisions relating to the Tribunal’s procedures generally, that apply to mental health inquiries and other proceedings, are set out in Part 2 of Chapter 6."]],"url":"https://legislation.nsw.gov.au/view/html/inforce/current/act-2007-008#/sec.34"},{"n":"35","heading":"Purpose and findings of mental health inquiries","lines":[[1,"(1) The Tribunal when holding a mental health inquiry is to determine whether or not, on the balance of probabilities, the assessable person is a mentally ill person."],[1,"(2) For that purpose, the Tribunal is to do the following—"],[2,"(a) consider the reports and recommendations of the authorised medical officer and other medical practitioners who examined the person under section 27 after the person’s detention,"],[2,"(b) consider any other information before the Tribunal,"],[2,"(c) inquire about the administration of any medication to the person and take account of its effect on the person’s ability to communicate,"],[2,"(d) have due regard to any cultural factors relating to the person that may be relevant to the determination,"],[2,"(e) have due regard to any evidence given at the inquiry by an expert witness concerning the person’s cultural background and its relevance to any question of mental illness."],[1,"(2A) As soon as practicable after the beginning of a mental health inquiry, the Tribunal must ask the assessable person whether the person—"],[2,"(a) has been given a written statement, in the prescribed form, of the person’s legal rights and other entitlements, as required by section 74, and"],[2,"(b) has been informed of the duty imposed under section 76 on the authorised medical officer relating to the giving of the notice specified in that section."],[1,"(2B) As soon as practicable after the beginning of a mental health inquiry, the Tribunal must ascertain from the authorised medical officer whether the written statement and notice referred to in subsection (2A) have been given or all such things as are reasonably practicable have been done to give that statement or notice, as the case requires."],[1,"(3) If the Tribunal is not satisfied, on the balance of probabilities, that an assessable person is a mentally ill person, the Tribunal must order that the person be discharged from the mental health facility."],[1,"(4) The Tribunal may defer the operation of an order for the discharge of a person for a period of up to 14 days, if the Tribunal thinks it is in the best interests of the person to do so."],[1,"(5) If the Tribunal is satisfied, on the balance of probabilities, that an assessable person is a mentally ill person, the Tribunal may make any of the following orders—"],[2,"(a) an order that the person be discharged into the care of a designated carer or the principal care provider of the person,"],[2,"(b) a community treatment order,"],[2,"(c) an order that the person be detained in or admitted to and detained in a mental health facility for further observation or treatment, or both, as an involuntary patient, for a specified period of up to 3 months, if the Tribunal is of the opinion that no other care of a less restrictive kind, that is consistent with safe and effective care, is appropriate and reasonably available or that for any other reason it is not appropriate to make any other order under this subsection."]],"url":"https://legislation.nsw.gov.au/view/html/inforce/current/act-2007-008#/sec.35"},{"n":"36","heading":"Adjournments","lines":[[1,"(1) The Tribunal may, from time to time, adjourn a mental health inquiry for a period not exceeding 14 days."],[1,"(2) Without limiting subsection (1), the Tribunal may adjourn the inquiry if it is not satisfied—"],[2,"(a) that the assessable person has been informed of the duty imposed under section 76 on the authorised medical officer relating to the giving of the notice specified in that section, or"],[2,"(b) that the notice specified in the section has been given or all such things as are reasonably practicable have been done to give that notice."],[1,"(3) The Tribunal may adjourn an inquiry under this section only if—"],[2,"(a) the Tribunal is of the opinion that it is in the best interests of the assessable person to do so, and"],[2,"(b) the Tribunal has considered any certificates given under this Act available to the Tribunal."],[1,"(4) If an inquiry is adjourned, the assessable person is to continue to be detained in the mental health facility unless the person is discharged or allowed to be absent from the facility under another provision of this Act."]],"url":"https://legislation.nsw.gov.au/view/html/inforce/current/act-2007-008#/sec.36"},{"n":"37","heading":"Reviews of involuntary patients by Tribunal","lines":[[1,"(1) The Tribunal must review the case of each involuntary patient as follows—"],[2,"(a) at the end of the patient’s initial period of detention as a result of a mental health inquiry,"],[2,"(b) at least once every 3 months for the first 12 months the person is an involuntary patient,"],[2,"(c) at least once every 6 months while the person is an involuntary patient after the first 12 months of detention."],[1,"(1A) The Tribunal may review the case of an involuntary patient at such other times as it sees fit."],[1,"(2) An authorised medical officer must cause an involuntary patient to be brought before the Tribunal—"],[2,"(a) as soon as practicable before the end of the initial period of detention, if it appears to the officer that the person should continue to be detained, and"],[2,"(b) at such other times as may be required by the Tribunal for the purposes of any review under this section."],[1,"(3) The authorised medical officer must ensure that, as far as practicable, a person brought before the Tribunal is dressed in street clothes."],[1,"(3A) The Tribunal may review the case of an involuntary patient in the absence of the patient if—"],[2,"(a) the authorised medical officer applies to have the review carried out in the absence of the patient because the patient has refused to attend the review or because the officer is of the opinion that the patient is too unwell to attend the review, and"],[2,"(b) the Tribunal is satisfied that the patient has refused to attend or is too unwell to attend and is unlikely to be well enough to attend within a reasonable period, and"],[2,"(c) the Tribunal is satisfied that any representative of the patient (being an Australian legal practitioner, or other person approved by the Tribunal, who is representing the patient for the purposes of the review) has been notified of the review, and"],[2,"(d) the Tribunal has considered the views (if known) of each of the following—"],[3,"(i) the patient,"],[3,"(ii) any representative of the patient,"],[3,"(iii) the designated carer of the patient,"],[3,"(iv) the principal care provider of the patient, and"],[2,"(e) the Tribunal is of the opinion that carrying out the review in the absence of the patient is desirable for the safety or welfare of the patient."],[1,"(4) Despite subsection (1) (c), the Tribunal may review the case of an involuntary patient at intervals of up to 12 months if it is of the opinion that it is appropriate to do so."]],"url":"https://legislation.nsw.gov.au/view/html/inforce/current/act-2007-008#/sec.37"},{"n":"38","heading":"Purpose and findings of reviews of involuntary patients","lines":[[1,"(1) The Tribunal is, on a review of an involuntary patient, to determine whether the patient is a mentally ill person for whom no other care (other than care in a mental health facility) is appropriate and reasonably available."],[1,"(2) For that purpose, the Tribunal is to do the following—"],[2,"(a) consider any information before it,"],[2,"(b) inquire about the administration of any medication to the patient and take account of its effect on the patient’s ability to communicate."],[1,"(3) If the Tribunal determines that the patient is not a mentally ill person, the patient must be discharged from the mental health facility in which the patient is detained."],[1,"(4) If the Tribunal determines that the patient is a mentally ill person and that no other care of a less restrictive kind, that is consistent with safe and effective care, is appropriate and reasonably available to the patient, the Tribunal must make an order that the patient continue to be detained as an involuntary patient in a mental health facility for further observation or treatment, or both."],[1,"(5) In any other case that the Tribunal determines that a patient is a mentally ill person, it must make an order that the patient be discharged from the mental health facility in which the patient is detained and may make any of the following orders—"],[2,"(a) an order that the patient be discharged into the care of a designated carer or the principal care provider of the person,"],[2,"(b) a community treatment order."],[1,"(6) The Tribunal may defer the operation of an order for the discharge of a patient for a period of up to 14 days, if the Tribunal thinks it is in the best interests of the patient to do so."],[1,"(7) An order made by the Tribunal under this section is to be in the form approved by the President."]],"url":"https://legislation.nsw.gov.au/view/html/inforce/current/act-2007-008#/sec.38"},{"n":"40","heading":"Re-classification of involuntary patients as voluntary patients","lines":[[1,"(1) An involuntary patient may be classified as a voluntary patient of the mental health facility in which the patient is detained—"],[2,"(a) by an authorised medical officer at any time, or"],[2,"(b) by the Tribunal when conducting a review of the patient."],[1,"(2) A patient may be so classified only if—"],[2,"(a) the authorised medical officer or Tribunal is of the opinion that the patient is likely to benefit from care or treatment as a voluntary patient, and"],[2,"(b) the patient agrees to be so classified or, if the patient is a person under guardianship, the patient is admitted in accordance with the procedures under this Act applicable to admitting such persons as voluntary patients."],[1,"(3) Without limiting subsection (1), a person who is discharged as an involuntary patient may be admitted as a voluntary patient immediately on discharge."],[0,"Note: Note. For additional circumstances when a patient or person must be released from a mental health facility, see section 12."]],"url":"https://legislation.nsw.gov.au/view/html/inforce/current/act-2007-008#/sec.40"},{"n":"41","heading":"Discharge on making of community treatment order","lines":[[1,"(1) An authorised medical officer must discharge a patient or person who is detained in a mental health facility when a community treatment order is made about the patient or person and any order authorising the patient’s or person’s detention ceases to have effect."],[1,"(2) This section does not prevent an affected person subject to a community treatment order from being admitted to or detained in a mental health facility."],[1,"(3) This section is subject to any order made under section 53 deferring the discharge of an involuntary patient."]],"url":"https://legislation.nsw.gov.au/view/html/inforce/current/act-2007-008#/sec.41"},{"n":"42","heading":"Discharge of involuntary patients on own application","lines":[[1,"(1) An involuntary patient of a mental health facility or another person detained in a mental health facility may make an application to the authorised medical officer to be discharged."],[1,"(2) The authorised medical officer may discharge the patient or person."],[1,"Note: Note. The authorised medical officer may also classify a patient as a voluntary patient (see section 40)."]],"url":"https://legislation.nsw.gov.au/view/html/inforce/current/act-2007-008#/sec.42"},{"n":"43","heading":"Discharge of involuntary patients on application of designated carer or principal care provider","lines":[[1,"(1) Any designated carer or the principal care provider of an involuntary patient or another person detained in a mental health facility may, at any time, apply to an authorised medical officer of the mental health facility for the discharge of the patient or person."],[1,"(2) The authorised medical officer may discharge the patient or person if—"],[2,"(a) the applicant gives the authorised medical officer a written undertaking that the patient or person will be properly taken care of, and"],[2,"(b) the authorised medical officer is satisfied that adequate measures will, so far as is reasonably practicable, be taken to prevent the patient or person from causing harm to himself or herself or others."]],"url":"https://legislation.nsw.gov.au/view/html/inforce/current/act-2007-008#/sec.43"},{"n":"44","heading":"Appeals against discharge refusals","lines":[[1,"(1) An involuntary patient or person detained at a mental health facility (the applicant) who applies to be discharged, or a person who applies for the discharge of the applicant, or a person appointed by the applicant, may appeal to the Tribunal if—"],[2,"(a) the authorised medical officer refuses the application, or"],[2,"(b) the authorised medical officer fails to determine the application within 3 working days after it is made."],[1,"(2) An appeal may be made orally or in writing and is to be made in accordance with the regulations."],[1,"(3) The authorised medical officer must provide the Tribunal with a report about the applicant, including the officer’s reasons for refusing to discharge the applicant or failing to determine the application."],[1,"(4) For the purpose of determining an appeal, the Tribunal has and may exercise the functions of the authorised medical officer with respect to the discharge application and may make an order accordingly."],[1,"(5) In addition, the Tribunal may determine that no further right of appeal may be exercised under this section before the date on which the person is next reviewed by the Tribunal under this Act, if it thinks it appropriate to do so, having regard to the following—"],[2,"(a) the interval between the last determination under this Act that the applicant was a mentally ill person and the date of the appeal,"],[2,"(b) the frequency of appeals under this section made by or on behalf of the applicant,"],[2,"(c) the last report about the applicant by the authorised medical officer under this section,"],[2,"(d) any other matter the Tribunal considers relevant."],[1,"(6) The Tribunal may defer the operation of an order under this section for the discharge of a person for a period of up to 14 days, if the Tribunal decides it is in the best interests of the person to do so."],[1,"Note: Note. The Tribunal may, on application, make a community treatment order for an involuntary patient or detained person who is the subject of an appeal (see section 51)."]],"url":"https://legislation.nsw.gov.au/view/html/inforce/current/act-2007-008#/sec.44"},{"n":"47","heading":"Leave of absence on compassionate grounds, medical grounds or other grounds","lines":[[1,"(1) An authorised medical officer may permit a person to be absent from a mental health facility for the period, and on the conditions, that the officer thinks fit."],[1,"(2) Permission may be given on compassionate grounds, on the ground that medical treatment is required or on any other ground the authorised medical officer thinks fit."],[1,"Note: Note. A person may also be transferred from a mental health facility to another health facility on medical grounds (see section 80)."],[1,"(3) An authorised medical officer may not grant leave of absence unless the officer is satisfied that, as far as is practicable, adequate measures have been taken to prevent the person concerned from causing harm to himself or herself or others."]],"url":"https://legislation.nsw.gov.au/view/html/inforce/current/act-2007-008#/sec.47"},{"n":"48","heading":"Apprehension of persons not permitted to be absent from mental health facility","lines":[[1,"(1) An authorised medical officer of a mental health facility may apprehend a person, or direct a person to be apprehended, if—"],[2,"(a) the person fails to return to the facility on or before the expiry of a permitted period of absence granted under this Part or fails to comply with a condition of the permission, or"],[2,"(b) the person absents himself or herself from the facility otherwise than in accordance with this Act."],[1,"(2) The person may be apprehended by any of the following persons—"],[2,"(a) an authorised medical officer or any other suitably qualified person employed at the mental health facility,"],[2,"(b) a police officer,"],[2,"(c) a person authorised by the Minister or the authorised medical officer,"],[2,"(d) a person assisting a person referred to in paragraph (a), (b) or (c)."],[1,"(3) A person who is apprehended is to be conveyed to and detained in the mental health facility from which the person absented himself or herself (whether directly or indirectly by way of another mental health facility)."]],"url":"https://legislation.nsw.gov.au/view/html/inforce/current/act-2007-008#/sec.48"},{"n":"51","heading":"Community treatment orders","lines":[[1,"(1) A community treatment order authorising the compulsory treatment in the community of a person may be made by the Tribunal."],[1,"Note: Note. Section 56 sets out the matters to be included in community treatment orders."],[1,"(2) The following persons may apply for a community treatment order for the treatment of a person—"],[2,"(a) the authorised medical officer of a mental health facility in which the affected person is detained or is a patient under this Act,"],[2,"(b) a medical practitioner who is familiar with the clinical history of the affected person,"],[2,"(c) any other person prescribed by the regulations."],[1,"(3) An application may be made about a person who is detained in or a patient in a mental health facility or a person who is not in a mental health facility."],[1,"(4) An application may be made about a person who is subject to a current community treatment order."],[1,"(5) A community treatment order may be made in the following circumstances and may replace an existing order—"],[2,"(a) following a mental health inquiry,"],[2,"(b) on a review of a patient by the Tribunal,"],[2,"(c) on an application otherwise being made to the Tribunal."],[1,"(6) Without limiting subsection (5) (c), an application for a community treatment order may be made, and determined by the Tribunal, in the same proceedings as an appeal under section 44."]],"url":"https://legislation.nsw.gov.au/view/html/inforce/current/act-2007-008#/sec.51"},{"n":"52","heading":"Notice of applications","lines":[[1,"(1) The applicant for a community treatment order must notify the affected person in writing of the application."],[1,"(2) The notice of the application is to include a copy of the proposed treatment plan for the affected person."],[1,"(3) If the affected person is not detained in a mental health facility, the application must be heard not earlier than 14 days after the notice is given to the affected person."],[1,"(4) Subsection (3) does not apply—"],[2,"(a) to an application for a further community treatment order in respect of an affected person who was the subject of a current community treatment order when the notice was given, or"],[2,"(b) if the Tribunal decides it is in the best interests of the affected person that the application be heard earlier than 14 days after the notice is given."],[1,"(5) As soon as practicable after becoming aware of the application, the director of community treatment of the declared mental health facility at which the treatment plan is proposed to be implemented must take all reasonably practicable steps to give written notice of the application to—"],[2,"(a) each designated carer of the affected person, and"],[2,"(b) the principal care provider of the affected person, if the principal care provider is not a designated carer."]],"url":"https://legislation.nsw.gov.au/view/html/inforce/current/act-2007-008#/sec.52"},{"n":"53","heading":"Determination of applications for community treatment orders","lines":[[1,"(1) The Tribunal is, on an application for a community treatment order, to determine whether the affected person is a person who should be subject to the order."],[1,"(2) For that purpose, the Tribunal is to consider the following—"],[2,"(a) a treatment plan for the affected person proposed by the declared mental health facility that is to implement the proposed order,"],[2,"(b) if the affected person is subject to an existing community treatment order, a report by the psychiatric case manager of the person as to the efficacy of that order,"],[2,"(c) a report as to the efficacy of any previous community treatment order for the affected person,"],[2,"(d) any other information placed before the Tribunal."],[1,"(3) The Tribunal may make a community treatment order for an affected person if the Tribunal determines that—"],[2,"(a) no other care of a less restrictive kind, that is consistent with safe and effective care, is appropriate and reasonably available to the person and that the affected person would benefit from the order as the least restrictive alternative consistent with safe and effective care, and"],[2,"(b) a declared mental health facility has an appropriate treatment plan for the affected person and is capable of implementing it, and"],[2,"(c) if the affected person has been previously diagnosed as suffering from a mental illness, the affected person has a previous history of refusing to accept appropriate treatment."],[1,"(3A) If the affected person has within the last 12 months been a forensic patient or the subject of a community treatment order, the Tribunal is not required to make a determination under subsection (3) (c) but must be satisfied that the person is likely to continue in or to relapse into an active phase of mental illness if the order is not granted."],[1,"(4) The Tribunal may not make a community treatment order at a mental health inquiry unless the Tribunal is of the opinion that the person is a mentally ill person."],[1,"(5) For the purposes of this section, a person has a previous history of refusing to accept appropriate treatment if the following are satisfied—"],[2,"(a) the affected person has previously refused to accept appropriate treatment,"],[2,"(b) when appropriate treatment has been refused, there has been a relapse into an active phase of mental illness,"],[2,"(c) the relapse has been followed by mental or physical deterioration justifying involuntary admission to a mental health facility (whether or not there has been such an admission),"],[2,"(d) care and treatment following involuntary admission resulted, or could have resulted, in an amelioration of, or recovery from, the debilitating symptoms of a mental illness or the short-term prevention of deterioration in the mental or physical condition of the affected person."],[1,"(6) The Tribunal must not specify a period longer than 12 months as the period for which a community treatment order is in force."],[1,"(7) In determining the duration of a community treatment order, the Tribunal must take into account the estimated time required—"],[2,"(a) to stabilise the condition of the affected person, and"],[2,"(b) to establish, or re-establish, a therapeutic relationship between the person and the person’s psychiatric case manager."],[1,"(8) The Tribunal may order that the discharge of an involuntary patient for whom a community treatment order is made be deferred for a period of up to 14 days, if the Tribunal thinks it is in the best interests of the patient to do so."]],"url":"https://legislation.nsw.gov.au/view/html/inforce/current/act-2007-008#/sec.53"},{"n":"54","heading":"Requirements for treatment plans under community treatment orders","lines":[[0,"A treatment plan for an affected person is to consist of the following—"],[1,"(a) in general terms, an outline of the proposed treatment, counselling, management, rehabilitation or other services to be provided to implement the community treatment order,"],[1,"(b) in specific terms, the method by which, the frequency with which, and the place at which, the services would be provided for that purpose."]],"url":"https://legislation.nsw.gov.au/view/html/inforce/current/act-2007-008#/sec.54"},{"n":"56","heading":"Form and duration of community treatment orders","lines":[[1,"(1) A community treatment order is to—"],[2,"(a) nominate the declared mental health facility that is to implement the treatment plan for the affected person, and"],[2,"(b) require the affected person to be present, at the reasonable times and places specified in the order to receive the medication and therapy, counselling, management, rehabilitation and other services provided in accordance with the treatment plan."],[1,"(2) A community treatment order ceases to have effect at the end of the period specified in the order or, if no period is specified, 12 months after the order is made."],[1,"Note: Note. Section 53 (6) specifies that the maximum period for an order is to be 12 months."],[1,"(3) A community treatment order has no effect while an affected person is detained in a mental health facility (otherwise than under this Part), or is a voluntary patient."],[1,"(4) The fact that an affected person is the subject of proceedings before the Tribunal does not, unless the Tribunal otherwise orders, affect the operation or duration of the community treatment order."],[1,"(5) The time for which a community treatment order is in force does not cease to run during any period in which this section provides that it has no effect."],[0,"Note: Note. The Tribunal may vary or revoke a community treatment order in accordance with section 65."]],"url":"https://legislation.nsw.gov.au/view/html/inforce/current/act-2007-008#/sec.56"},{"n":"58","heading":"Breach of community treatment order","lines":[[1,"(1) The director of community treatment of a declared mental health facility implementing a community treatment order must take the steps set out in this section if the affected person in any way refuses or fails to comply with the community treatment order and the director is of the opinion that—"],[2,"(a) the mental health facility has taken all reasonable steps to implement the order, and"],[2,"(b) there is a significant risk of deterioration in the mental or physical condition of the affected person."],[1,"(2) The director must—"],[2,"(a) make a written record of the opinions, the facts on which they are based and the reasons for forming them, and"],[2,"(b) cause the affected person to be informed that any further refusal to comply with the order will result in the person being taken to the declared mental health facility or another appropriate mental health facility and treated there, and"],[2,"(c) take all reasonably practicable steps to notify the following persons of the action taken under paragraphs (a) and (b)—"],[3,"(i) each designated carer of the affected person,"],[3,"(ii) the principal care provider of the affected person, if the principal care provider is not a designated carer."],[1,"(3) On a further refusal or failure by the affected person to comply with the community treatment order, the director may cause the person to be given a written notice (a breach notice)—"],[2,"(a) requiring the person to accompany a member of staff of the NSW Health Service employed at the declared mental health facility for treatment in accordance with the order or to a specified mental health facility, and"],[2,"(b) warning the person that the assistance of a police officer may be obtained in order to ensure compliance with the order."],[1,"(4) On the refusal or failure by the affected person to comply with a breach notice, the director may, in writing, make an order (a breach order) that the affected person be taken to a specified declared mental health facility."],[1,"(5) For the purposes of subsection (3), the director causes a person to be given a breach notice if the director ensures that—"],[2,"(a) the notice is handed directly to the person, or"],[2,"(b) if it is not reasonably practicable to hand the notice directly to the person, the notice is given to the person in a way specified in section 192(1)(a)(ii), (iv) or (v)."],[1,"(6) The director must take all reasonably practicable steps to give a copy of a breach notice and a breach order to—"],[2,"(a) each designated carer of the affected person, and"],[2,"(b) the principal care provider of the affected person, if the principal care provider is not a designated carer."]],"url":"https://legislation.nsw.gov.au/view/html/inforce/current/act-2007-008#/sec.58"},{"n":"59","heading":"Police assistance","lines":[[1,"(1) A police officer to whose notice a breach order is brought must, if practicable—"],[2,"(a) apprehend and take or assist in taking the person the subject of the order to the mental health facility, or"],[2,"(b) cause or make arrangements for some other police officer to do so."],[1,"(2) A police officer may enter premises to apprehend a person under this section, and may apprehend any such person, without a warrant and may exercise any powers conferred by section 81 on a person who is authorised under that section to take a person to a mental health facility or another health facility."],[1,"Note: Note. Section 81 sets out the persons who may take a person to a mental health facility and their powers when doing so."]],"url":"https://legislation.nsw.gov.au/view/html/inforce/current/act-2007-008#/sec.59"},{"n":"60","heading":"Procedures at facility after breach notice or breach order","lines":[[1,"(1) An affected person who is at a mental health facility as a result of the giving of a breach notice or a breach order—"],[2,"(a) may be given treatment in accordance with the community treatment order, and"],[2,"(b) may be assessed by a medical practitioner for involuntary admission to a mental health facility."],[1,"(2) A person who is at a mental health facility as a result of a breach notice or breach order may be released after treatment if treatment is accepted or may be dealt with at the mental health facility or taken to another declared mental health facility if treatment is refused."]],"url":"https://legislation.nsw.gov.au/view/html/inforce/current/act-2007-008#/sec.60"},{"n":"61","heading":"Review of affected person at mental health facility after breach order","lines":[[1,"(1) This section applies to an affected person who is taken to or is at a declared mental health facility after refusing treatment at a mental health facility consequent on a breach order."],[1,"(2) An authorised medical officer must, not later than 12 hours after the person is taken to the declared mental health facility, review the affected person’s mental condition and determine whether the person is a mentally ill person or a mentally disordered person."],[1,"(3) The authorised medical officer may cause the person to be given treatment in accordance with the community treatment order."],[1,"(4) If the authorised medical officer determines that the affected person is a mentally ill person or a mentally disordered person for whom no other care of a less restrictive kind, that is consistent with safe and effective care, is appropriate or reasonably available, the person is to be detained in the declared mental health facility for further observation or treatment, or both."],[1,"(5) The affected person may be detained until one of the following events occurs—"],[2,"(a) in the case of a mentally ill person, the term of the community treatment order ends or the person is discharged from the declared mental health facility under this Act,"],[2,"(b) in the case of a mentally disordered person, the maximum period for which a person may be held as such a person under Part 2 ends, the term of the community treatment order ends or the person is discharged from the declared mental health facility under this Act."]],"url":"https://legislation.nsw.gov.au/view/html/inforce/current/act-2007-008#/sec.61"},{"n":"61A","heading":"Medical examination of detained affected persons","lines":[[1,"(1) An authorised medical officer must medically examine each affected person detained in a mental health facility to determine whether the person’s continued detention in the facility is necessary."],[1,"(2) The medical examinations are to be carried out at intervals of not more than 3 months."]],"url":"https://legislation.nsw.gov.au/view/html/inforce/current/act-2007-008#/sec.61a"},{"n":"62","heading":"Discharge and detention of affected persons","lines":[[1,"(1) An affected person detained in a declared mental health facility under this Division must be discharged from the facility—"],[2,"(a) if the authorised medical officer determines that the person is not a mentally ill person or a mentally disordered person or is of the opinion that other care of a less restrictive kind, that is consistent with safe and effective care, is appropriate and reasonably available to the person, or"],[2,"(b) if the authorised medical officer decides at any time that it is appropriate to do so."],[1,"(2) An authorised medical officer may do all necessary things to cause a person to be detained in a mental health facility under Part 2 at the end of the term of a community treatment order if the officer considers the person to be a mentally ill person."],[1,"(3) Any such person is taken to be detained in the mental health facility under section 19 when the authorised medical officer takes action to detain the person."]],"url":"https://legislation.nsw.gov.au/view/html/inforce/current/act-2007-008#/sec.62"},{"n":"63","heading":"Review of detained affected persons by Tribunal","lines":[[1,"(1) An authorised medical officer must cause a person detained in a declared mental health facility under this Division to be brought before the Tribunal not later than 3 months after the person is detained, and at least every 3 months while the person is detained."],[1,"(2) The authorised medical officer must ensure that, as far as practicable, a person brought before the Tribunal is dressed in street clothes."],[1,"(2A) The Tribunal may review the case of the affected person in the absence of the affected person if—"],[2,"(a) the authorised medical officer applies to have the review carried out in the absence of the affected person because the affected person has refused to attend the review or because the officer is of the opinion that the affected person is too unwell to attend the review, and"],[2,"(b) the Tribunal is satisfied that the affected person has refused to attend or is too unwell to attend and is unlikely to be well enough to attend within a reasonable period, and"],[2,"(c) the Tribunal is satisfied that any representative of the affected person (being an Australian legal practitioner, or other person approved by the Tribunal, who is representing the affected person for the purposes of the review) has been notified of the review, and"],[2,"(d) the Tribunal has considered the views (if known) of each of the following—"],[3,"(i) the affected person,"],[3,"(ii) any representative of the affected person,"],[3,"(iii) the designated carer of the affected person,"],[3,"(iv) the principal care provider of the affected person, and"],[2,"(e) The Tribunal is of the opinion that carrying out the review in the absence of the affected person is desirable for the safety or welfare of the affected person."],[1,"(3) This section does not apply if the affected person’s community treatment order will end less than 3 months after the person is detained under this Division."]],"url":"https://legislation.nsw.gov.au/view/html/inforce/current/act-2007-008#/sec.63"},{"n":"65","heading":"Variation or revocation of orders by Tribunal","lines":[[1,"(1) The Tribunal may vary or revoke a community treatment order, on application being made under this section or at any time on its own motion."],[1,"(2) An application may be made by any of the following—"],[2,"(a) the affected person,"],[2,"(b) the psychiatric case manager of the affected person,"],[2,"(c) any person who could have applied for the order."],[1,"(3) An application may be made only if—"],[2,"(a) there has been a substantial or material change in the circumstances surrounding the making of the order, or"],[2,"(b) relevant information that was not available when the order was made has become available."],[1,"(4) An order may be varied only if the order, as varied, could be made in relation to the affected person."],[1,"(5) The regulations may make provision for or with respect to applications under this section and the orders that may be made by the Tribunal."]],"url":"https://legislation.nsw.gov.au/view/html/inforce/current/act-2007-008#/sec.65"},{"n":"66","heading":"Revocation by director of community treatment","lines":[[1,"(1) The director of community treatment of a declared mental health facility implementing a treatment plan under a community treatment order may revoke a community treatment order if of the opinion that the affected person is not likely to benefit from a continuation of the order."],[1,"(2) Before revoking a community treatment order, the director must consult the affected person and, if it is reasonably practicable to do so, any designated carer and the principal care provider of the affected person (if the principal care provider is not a designated carer)."],[1,"(3) The director must notify the Tribunal in writing if the director revokes a community treatment order or decides not to apply to the Tribunal for a further order."]],"url":"https://legislation.nsw.gov.au/view/html/inforce/current/act-2007-008#/sec.66"},{"n":"66A","heading":"Notifications","lines":[[0,"The director of community treatment of the declared mental health facility implementing a community treatment order must take all reasonably practicable steps to notify any designated carer and the principal care provider of the affected person (if the principal care provider is not a designated carer) of the order and if any of the following events occur—"],[1,"(a) the order is varied or revoked by the Tribunal or director,"],[1,"(b) an application is made for a further order or the director decides not to apply for a further order."]],"url":"https://legislation.nsw.gov.au/view/html/inforce/current/act-2007-008#/sec.66a"},{"n":"68","heading":"Principles for care and treatment","lines":[[0,"It is the intention of Parliament that the following principles are, as far as practicable, to be given effect to with respect to the care and treatment of people with a mental illness or mental disorder—"],[1,"(a) people with a mental illness or mental disorder should receive the best possible care and treatment in the least restrictive environment enabling the care and treatment to be effectively given,"],[1,"(b) people with a mental illness or mental disorder should be provided with timely and high quality treatment and care in accordance with professionally accepted standards,"],[1,"(c) the provision of care and treatment should be designed to assist people with a mental illness or mental disorder, wherever possible, to live, work and participate in the community,"],[1,"(d) the prescription of medicine to a person with a mental illness or mental disorder should meet the health needs of the person and should be given only for therapeutic or diagnostic needs and not as a punishment or for the convenience of others,"],[1,"(e) people with a mental illness or mental disorder should be provided with appropriate information about treatment, treatment alternatives and the effects of treatment and be supported to pursue their own recovery,"],[1,"(f) any restriction on the liberty of patients and other people with a mental illness or mental disorder and any interference with their rights, dignity and self-respect is to be kept to the minimum necessary in the circumstances,"],[1,"(g) any special needs of people with a mental illness or mental disorder should be recognised, including needs related to age, gender, religion, culture, language, disability or sexuality,"],[1,"(g1) people under the age of 18 years with a mental illness or mental disorder should receive developmentally appropriate services,"],[1,"(g2) the cultural and spiritual beliefs and practices of people with a mental illness or mental disorder who are Aboriginal persons or Torres Strait Islanders should be recognised,"],[1,"(h) every effort that is reasonably practicable should be made to involve persons with a mental illness or mental disorder in the development of treatment plans and recovery plans and to consider their views and expressed wishes in that development,"],[1,"(h1) every effort that is reasonably practicable should be made to obtain the consent of people with a mental illness or mental disorder when developing treatment plans and recovery plans for their care, to monitor their capacity to consent and to support people who lack that capacity to understand treatment plans and recovery plans,"],[1,"(i) people with a mental illness or mental disorder should be informed of their legal rights and other entitlements under this Act and all reasonable efforts should be made to ensure the information is given in the language, mode of communication or terms that they are most likely to understand,"],[1,"(j) the role of carers for people with a mental illness or mental disorder and their rights under this Act to be kept informed, to be involved and to have information provided by them considered, should be given effect."]],"url":"https://legislation.nsw.gov.au/view/html/inforce/current/act-2007-008#/sec.68"},{"n":"69","heading":"Offence to ill-treat patients","lines":[[0,"An authorised medical officer, or any other person employed at a mental health facility, must not wilfully strike, wound, ill-treat or neglect a patient or person detained at the facility under this or any other Act."],[1,"Maximum penalty—50 penalty units or imprisonment for 6 months, or both."]],"url":"https://legislation.nsw.gov.au/view/html/inforce/current/act-2007-008#/sec.69"},{"n":"69A","heading":"Prohibition on use of spit hoods","lines":[[1,"(1) An authorised medical officer, or another person, exercising functions under this Act must not use a spit hood in the exercise of the functions."],[1,"Note: Note— A contravention of this subsection may constitute an unauthorised or unreasonable use of force."],[1,"(2) Subsection (1)—"],[2,"(a) applies despite any other provision of this Act or another Act or law, and"],[2,"(b) does not limit section 69."],[1,"(3) In this section—"],[2,"spit hood—"],[3,"(a) means a covering, however described, intended to be placed over a person’s head to prevent the person from spitting on, or biting, another person, but"],[3,"(b) does not include a helmet designed to prevent self-harm, even if the helmet incorporates a part designed to stop spittle."]],"url":"https://legislation.nsw.gov.au/view/html/inforce/current/act-2007-008#/sec.69a"},{"n":"70","heading":"Assistance of interpreters","lines":[[0,"A medical practitioner must arrange for an interpreter to be present at a medical examination of a person for the purposes of this Act, if the person is unable to communicate adequately in English but can communicate adequately in another language."]],"url":"https://legislation.nsw.gov.au/view/html/inforce/current/act-2007-008#/sec.70"},{"n":"71","heading":"Designated carers","lines":[[1,"(1) The designated carer of a person (the patient) for the purposes of this Act is—"],[2,"(a) the guardian of the patient, or"],[2,"(b) the parent of a patient who is a child (subject to any nomination by a patient referred to in paragraph (c)), or"],[2,"(c) if the patient is over the age of 14 years and is not a person under guardianship, a person nominated by the patient as a designated carer under this Part under a nomination that is in force, or"],[2,"(d) if the patient is not a patient referred to in paragraph (a) or (b) or there is no nomination in force as referred to in paragraph (c)—"],[3,"(i) the spouse of the patient, if any, if the relationship between the patient and the spouse is close and continuing, or"],[3,"(ii) any individual who is primarily responsible for providing support or care to the patient (other than wholly or substantially on a commercial basis), or"],[3,"(iii) a close friend or relative of the patient."],[1,"(2) In this section—"],[2,"close friend or relative of a patient means a friend or relative of the patient who maintains both a close personal relationship with the patient through frequent personal contact and a personal interest in the patient’s welfare and who does not provide support to the patient wholly or substantially on a commercial basis."],[2,"relative of a patient who is an Aboriginal person or a Torres Strait Islander includes a person who is part of the extended family or kin of the patient according to the indigenous kinship system of the patient’s culture."]],"url":"https://legislation.nsw.gov.au/view/html/inforce/current/act-2007-008#/sec.71"},{"n":"72","heading":"Nomination of designated carers","lines":[[1,"(1) A person may nominate up to 2 persons to be the person’s designated carers for the purposes of this Act."],[1,"(2) A person may nominate persons who are excluded from being given notice or information about the person under this Act and may revoke or vary any such nomination."],[1,"(3) A person who is over the age of 14 years and under the age of 18 years may not exclude the person’s parent by a nomination under subsection (2)."],[1,"(4) A nomination, variation or revocation is to be made in writing and may be given to an authorised medical officer at a mental health facility or a director of community treatment."],[1,"(5) A nomination remains in force for the period prescribed by the regulations or until it is revoked in writing."],[1,"(6) An authorised medical officer or a director of community treatment is, in carrying out his or her functions under this Act or the regulations, to give effect to a nomination or a variation or revocation of a nomination, if notified of the nomination, variation or revocation."],[1,"(7) An authorised medical officer or a director of community treatment is not required to give effect to a nomination, or a variation or revocation of a nomination, if the officer or director reasonably believes—"],[2,"(a) that to do so may put the patient or nominated person or any other person at risk of serious harm, or"],[2,"(b) that the person who made the nomination, variation or revocation was incapable of making the nomination, variation or revocation."]],"url":"https://legislation.nsw.gov.au/view/html/inforce/current/act-2007-008#/sec.72"},{"n":"72A","heading":"Principal care providers","lines":[[1,"(1) The principal care provider of a person for the purposes of this Act is the individual who is primarily responsible for providing support or care to the person (other than wholly or substantially on a commercial basis)."],[1,"(2) An authorised medical officer at a mental health facility or a director of community treatment may, for the purposes of complying with a provision of this Act or the regulations, determine who is the principal care provider of a person."],[1,"(3) The authorised medical officer or the director of community treatment must not determine that a person is the principal care provider of another person if the person is excluded from being given notice or information about the other person under this Act."],[1,"(4) An authorised medical officer or a director of community treatment is not required to give effect to a requirement relating to a principal care provider of a person under this Act or the regulations if the officer or director reasonably believes that to do so may put the person or the principal care provider at risk of serious harm."],[1,"(5) A principal care provider of a person may also be a designated carer of the person."]],"url":"https://legislation.nsw.gov.au/view/html/inforce/current/act-2007-008#/sec.72a"},{"n":"72B","heading":"Requirement to consider information provided by other persons about patients or detained persons when making detention or discharge decisions","lines":[[0,"An authorised medical officer or other medical practitioner or accredited person who examines an involuntary patient or person detained in a mental health facility for the purposes of determining whether the person is a mentally ill person or a mentally disordered person or whether to discharge the patient or person is to consider any information provided by the following persons, if it is reasonably practicable to do so—"],[1,"(a) any designated carer, principal care provider, relative or friend of the patient or person,"],[1,"(b) any medical practitioner or other health professional who has treated the patient or person in relation to a relevant matter,"],[1,"(c) any person who brought the patient or person to the mental health facility."]],"url":"https://legislation.nsw.gov.au/view/html/inforce/current/act-2007-008#/sec.72b"},{"n":"73","heading":"Information about medication","lines":[[1,"(1) On a request made under this section, an authorised medical officer of a mental health facility must provide particulars of the types of medication and dosages of each type of medication currently being administered or recently administered to a patient or person detained in the facility."],[1,"(2) A request may be made by—"],[2,"(a) the patient or person detained in the mental health facility, or"],[2,"(b) any designated carer or the principal care provider of any such patient or person, or"],[2,"(c) a representative of any such patient or person at a mental health inquiry or before the Tribunal."]],"url":"https://legislation.nsw.gov.au/view/html/inforce/current/act-2007-008#/sec.73"},{"n":"74","heading":"Information to be given to persons to be detained","lines":[[1,"(1) An authorised medical officer of a mental health facility must give the following persons an oral explanation and a written statement of their legal rights and other entitlements under this Act—"],[2,"(a) a person who is taken to the facility under Part 2 of Chapter 3,"],[2,"(b) a person who is a voluntary patient in the facility, if it is decided to take steps to detain the person under Part 2 of Chapter 3,"],[2,"(c) an affected person who is detained in the facility after a breach notice or breach order relating to a community treatment order, if it is decided to take steps to detain the person under Part 2 of Chapter 3."],[1,"(2) The explanation and statement must be given as soon as practicable after the person is taken to a mental health facility or it is decided to take steps to detain the person."],[1,"(3) The written statement is to be in the form set out in Schedule 3."],[1,"(4) If the authorised medical officer is of the opinion that a person is not capable of understanding the explanation or statement when it is first given, another explanation or statement must be given to the person not later than 24 hours before a mental health inquiry is held about the person."],[1,"(5) The authorised medical officer must, if the person is unable to communicate adequately in English but is able to communicate adequately in another language, arrange for the oral explanation to be given in that other language."]],"url":"https://legislation.nsw.gov.au/view/html/inforce/current/act-2007-008#/sec.74"},{"n":"75","heading":"Notification to carers of initial detention","lines":[[1,"(1) An authorised medical officer must, not later than 24 hours after a person is detained in a mental health facility, take all reasonably practicable steps to notify any designated carer and the principal care provider (if the principal care provider is not a designated carer) of the person that the person is detained in the facility."],[1,"(2) Notice need not be given if the person is discharged or classified as a voluntary patient within that period."]],"url":"https://legislation.nsw.gov.au/view/html/inforce/current/act-2007-008#/sec.75"},{"n":"76","heading":"Notification of mental health inquiries","lines":[[1,"(1) An authorised medical officer must notify an assessable person detained in the mental health facility that—"],[2,"(a) a mental health inquiry will be held about the person, and"],[2,"(b) all reasonably practicable steps will be taken to give notice of the inquiry to any designated carer and the principal care provider of the person (if the principal care provider is not a designated carer)."],[1,"(2) The notice is to be given when the authorised medical officer becomes aware that the person is an assessable person."],[1,"(3) The authorised medical officer must, in accordance with the regulations, take all reasonably practicable steps to give notice to any designated carer and the principal care provider (if the principal care provider is not a designated carer) of an assessable person of a proposed mental health inquiry."]],"url":"https://legislation.nsw.gov.au/view/html/inforce/current/act-2007-008#/sec.76"},{"n":"77","heading":"Notification to new involuntary patients of appeal rights","lines":[[1,"(1) An authorised medical officer of a mental health facility must give, or cause to be given, to a person ordered by the Tribunal after a mental health inquiry to be detained in the facility as an involuntary patient a statement of the rights of appeal conferred on the person as an involuntary patient under this Act."],[1,"(1A) An authorised medical officer of a mental health facility must give, or cause to be given, to a person detained in the facility on the order of the Tribunal after a breach of a community treatment order a statement of the rights of appeal conferred on the person under this Act or the Mental Health and Cognitive Impairment Forensic Provisions Act 2020."],[1,"(2) The statement must be given as soon as practicable after the order is made."],[1,"(3) The statement is to be in the form approved by the Minister."]],"url":"https://legislation.nsw.gov.au/view/html/inforce/current/act-2007-008#/sec.77"},{"n":"78","heading":"Notifications to designated carers and principal care providers of events affecting patients or detained persons","lines":[[1,"(1) An authorised medical officer of a mental health facility must take all reasonably practicable steps to notify any designated carer and the principal care provider (if the principal care provider is not a designated carer) of a patient or person detained in the facility if any of the following events occurs—"],[2,"(a) the patient or person is absent from the facility without permission or fails to return at the end of a period of leave,"],[2,"(b) it is proposed to transfer the patient or person, or the patient or person is transferred, to another mental health facility or other facility,"],[2,"(c) the patient or person is discharged from the mental health facility,"],[2,"(d) the patient or person is re-classified as a voluntary patient,"],[2,"(e) it is proposed to apply to the Tribunal for an ECT inquiry under Part 2 or to ascertain whether the patient or person is capable of giving informed consent to electro convulsive therapy,"],[2,"(f) a surgical operation is performed on the patient or person under Part 3,"],[2,"(g) it is proposed to apply to the Secretary or the Tribunal for consent to a surgical operation or special medical treatment under Part 3,"],[2,"(h) the patient or person has any matter before the Tribunal."],[1,"(2) The authorised medical officer must give the notice as soon as practicable after becoming aware that the event has occurred."],[1,"(3) In the case of a proposed transfer, the notice must be given before the relevant order or arrangement is made, except in an emergency."]],"url":"https://legislation.nsw.gov.au/view/html/inforce/current/act-2007-008#/sec.78"},{"n":"79","heading":"Discharge and other planning","lines":[[1,"(1) An authorised medical officer of a mental health facility must take all reasonably practicable steps to ensure that a patient or person detained in the facility, and any designated carer and the principal care provider (if the principal care provider is not a designated carer) of the patient or person, are consulted in relation to planning the patient’s or person’s discharge and any subsequent treatment or other action considered in relation to the patient or person."],[1,"(2) In planning the discharge of any such patient or person, and any subsequent treatment or other action considered in relation to the patient or person, the authorised medical officer must take all reasonably practicable steps to consult with agencies involved in providing relevant services to the patient or person, any designated carer and the principal care provider (if the principal care provider is not a designated carer) of the patient or person and any dependent children or other dependants of the patient or person."],[1,"(3) An authorised medical officer of a mental health facility must take all reasonably practicable steps to provide any such patient or person who is discharged from the facility, and any designated carer and the principal care provider (if the principal care provider is not a designated carer) of the patient or person, with appropriate information as to follow-up care."]],"url":"https://legislation.nsw.gov.au/view/html/inforce/current/act-2007-008#/sec.79"},{"n":"80","heading":"Transfer of patients to or from mental health facilities","lines":[[1,"(1) An involuntary patient or a person detained in a mental health facility may be transferred from the mental health facility to another mental health facility or another health facility."],[1,"(2) A person who is a patient in a health facility other than a mental health facility may be transferred from the health facility to a declared mental health facility for the purpose of detaining the person under Part 2 of Chapter 3."],[1,"Note: Note. Section 25 sets out the procedure for detaining such a person in a declared mental health facility."],[1,"(3) A transfer of a patient or person to a health facility other than a mental health facility may be made on the grounds that the patient or person requires medical treatment for a condition or illness (other than a mental illness or other mental condition)."],[1,"(4) A transfer under this section is to be done in accordance with an arrangement between medical officers of each facility or an order in writing by the Secretary."],[1,"(5) An arrangement under this section is sufficient authority for the transfer of a patient or person, and the reception into, the mental health facility or other health facility to which the patient or person is transferred."]],"url":"https://legislation.nsw.gov.au/view/html/inforce/current/act-2007-008#/sec.80"},{"n":"81","heading":"Transport of persons to and from mental health facilities and other health facilities","lines":[[1,"(1) The persons listed below may take to or from a mental health facility or another health facility any person who is authorised by this Act to be taken, or transferred, to or from the facility—"],[2,"(a) a member of staff of the NSW Health Service,"],[2,"(b) an ambulance officer,"],[2,"(c) a police officer,"],[2,"(d) a person prescribed by the regulations."],[1,"(2) A person authorised by this Act to take a person to or from a mental health facility or other health facility may—"],[2,"(a) use reasonable force in exercising functions under this section or any other provision of this Act applying this section, and"],[2,"(b) restrain the person in any way that is reasonably necessary in the circumstances."],[1,"(3) A person may be sedated, by a person authorised by law to administer the sedative, for the purpose of being taken to or from a mental health facility or other health facility under this Act if it is necessary to do so to enable the person to be taken safely to or from the facility."],[1,"Note: Note. The Poisons and Therapeutic Goods Act 1966, and the regulations under that Act, regulate the persons who may prescribe and administer drugs (including sedative drugs)."],[1,"(4) A person authorised by this Act to take a person to or from a mental health facility or other health facility may carry out a frisk search or an ordinary search of the person, if the person reasonably suspects that the other person is carrying anything—"],[2,"(a) that would present a danger to the person or any other person, or"],[2,"(b) that could be used to assist the other person to escape from the person’s custody."],[1,"(5) The person may seize and detain a thing found in a search if it is a thing of a kind referred to in subsection (4) (a) or (b)."],[1,"(6) In this section—"],[2,"frisk search means—"],[3,"(a) a search of a person conducted by quickly running the hands over the person’s outer clothing or by passing an electronic metal detection device over or in close proximity to the person’s outer clothing, or"],[3,"(b) an examination of anything worn or carried by the person that is conveniently and voluntarily removed by the person, including an examination conducted by passing an electronic metal detection device over or in close proximity to that thing."],[2,"ordinary search means a search of a person or of articles in the possession of the person that may include—"],[3,"(a) requiring the person to remove only his or her overcoat, coat or jacket or similar article of clothing and any gloves, shoes, socks and hat, and"],[3,"(b) an examination of those items."]],"url":"https://legislation.nsw.gov.au/view/html/inforce/current/act-2007-008#/sec.81"},{"n":"82","heading":"Definitions","lines":[[0,"In this Part—"],[1,"administer a treatment includes cause or knowingly permit treatment to be administered."],[1,"involuntary patient includes a forensic patient, correctional patient and a person detained in a mental health facility."]],"url":"https://legislation.nsw.gov.au/view/html/inforce/current/act-2007-008#/sec.82"},{"n":"83","heading":"Prohibited treatments","lines":[[1,"(1) A person must not administer to or perform on another person any of the following—"],[2,"(a) deep sleep therapy,"],[2,"(b) insulin coma therapy,"],[2,"(c) psychosurgery,"],[2,"(d) any other operation or treatment prescribed by the regulations for the purposes of this section."],[2,"Maximum penalty—50 penalty units."],[1,"(2) In this section—"],[2,"psychosurgery means—"],[3,"(a) the creation of 1 or more lesions, whether made on the same or separate occasions, in the brain of a person by any surgical technique or procedure, when it is done primarily for the purpose of altering the thoughts, emotions or behaviour of the person, or"],[3,"(b) the use for such a purpose of electrodes within the brain to produce such a lesion or lesions, whether on the same or separate occasions, or"],[3,"(c) the use on 1 or more occasions of electrodes within the brain primarily for the purpose of influencing or altering the thoughts, emotions or behaviour of a person by stimulation through the electrodes without the production of a lesion in the brain of the person,"],[2,"but does not include a technique or procedure carried out for the treatment of a condition or an illness prescribed by the regulations for the purposes of this definition."]],"url":"https://legislation.nsw.gov.au/view/html/inforce/current/act-2007-008#/sec.83"},{"n":"84","heading":"Treatment may be given to patients","lines":[[0,"An authorised medical officer of a mental health facility may, subject to this Act and the Mental Health and Cognitive Impairment Forensic Provisions Act 2020, give, or authorise the giving of, any treatment (including any medication) the officer thinks fit to an involuntary patient or assessable person detained in the facility in accordance with this Act or that Act."]],"url":"https://legislation.nsw.gov.au/view/html/inforce/current/act-2007-008#/sec.84"},{"n":"85","heading":"Administration of excessive or inappropriate drugs","lines":[[0,"A medical practitioner must not, in relation to any mental illness or mental condition or suspected mental illness or mental condition, administer, or cause to be administered to a person a drug or drugs in a dosage that, having regard to professional standards, is excessive or inappropriate."],[1,"Maximum penalty—50 penalty units."]],"url":"https://legislation.nsw.gov.au/view/html/inforce/current/act-2007-008#/sec.85"},{"n":"87","heading":"Definitions","lines":[[0,"In this Division—"],[1,"ECT administration inquiry—see section 96 (2)."],[1,"ECT consent inquiry—see section 96 (1)."],[1,"ECT determination—see section 96 (3)."],[1,"ECT inquiry means an ECT administration inquiry or an ECT consent inquiry."]],"url":"https://legislation.nsw.gov.au/view/html/inforce/current/act-2007-008#/sec.87"},{"n":"88","heading":"Offences relating to administration of electro convulsive treatment","lines":[[1,"(1) A person who is not a medical practitioner must not administer electro convulsive therapy to another person."],[1,"(2) A medical practitioner must not administer electro convulsive therapy to a person—"],[2,"(a) otherwise than in accordance with this Division, or"],[2,"(b) at a place other than a mental health facility or other place approved by the Secretary."],[1,"(3) A medical practitioner must not administer electro convulsive therapy to a person unless there are present during the administration of the electro convulsive therapy not less than 2 medical practitioners (of whom the medical practitioner administering the electro convulsive therapy may be one)—"],[2,"(a) one of whom is experienced in the administration of electro convulsive therapy, and"],[2,"(b) another of whom is experienced in the administration of anaesthesia."],[1,"Maximum penalty—50 penalty units."]],"url":"https://legislation.nsw.gov.au/view/html/inforce/current/act-2007-008#/sec.88"},{"n":"89","heading":"When electro convulsive therapy may be administered","lines":[[0,"Electro convulsive therapy may be administered only in the following circumstances—"],[1,"(a) to a person other than an involuntary patient or a person who is under the age of 16 years, if the person meets the requirements for informed consent to the treatment and medical certification set out in this Division,"],[1,"(b) to an involuntary patient or a person who is under the age of 16 years, after an ECT determination by the Tribunal at an ECT inquiry."]],"url":"https://legislation.nsw.gov.au/view/html/inforce/current/act-2007-008#/sec.89"},{"n":"91","heading":"Informed consent requirements","lines":[[1,"(1) A person is taken to have given informed consent to the administration of electro convulsive therapy if the person gives a free, voluntary and written consent after this section is complied with."],[1,"(2) The following steps must be taken before consent is obtained—"],[2,"(a) a fair explanation must be made to the person of the techniques or procedures to be followed, including an identification and explanation of any technique or procedure about which there is not sufficient data to recommend it as recognised treatment or to reliably predict the outcome of its performance,"],[2,"(b) a full description must be given, without exaggeration or concealment, to the person of any possible discomforts and risks of the treatment (including possible loss of memory),"],[2,"(c) a full description must be given to the person of any expected benefits of the treatment,"],[2,"(d) a full disclosure must be made, without exaggeration or concealment, to the person of any appropriate alternative treatments that would be advantageous to the person,"],[2,"(e) an offer must be made to the person to answer any inquiries concerning the procedures or any part of them,"],[2,"(f) the person must be given notice that the person is free to refuse or to withdraw consent and to discontinue the procedures or any part of them at any time,"],[2,"(g) a full disclosure must be made to the person of any financial relationship between the person proposing the administration of the treatment or the administering medical practitioner, or both, and the facility in which it is proposed to administer the treatment,"],[2,"(h) the person must be given notice of their right to obtain legal and medical advice and to be represented before giving consent,"],[2,"(i) any question relating to the techniques or procedures to be followed that is asked by the person must have been answered and the answers must appear to have been understood by the person,"],[2,"(j) a form setting out the steps in this subsection is to be given to the person and an oral explanation of the matters dealt with in the form is to be given to the person in a language with which the person is familiar."],[1,"(3) The regulations are to prescribe forms setting out the steps to be taken before obtaining informed consent to electro convulsive therapy."]],"url":"https://legislation.nsw.gov.au/view/html/inforce/current/act-2007-008#/sec.91"},{"n":"92","heading":"Person impaired by medication incapable of giving informed consent","lines":[[0,"A person is presumed to be incapable of giving informed consent to the administration of electro convulsive therapy if, when consent is sought, the person is affected by medication that impairs the person’s ability to give that consent."]],"url":"https://legislation.nsw.gov.au/view/html/inforce/current/act-2007-008#/sec.92"},{"n":"93","heading":"When electro convulsive therapy may be administered to persons other than involuntary patients or persons under 16","lines":[[1,"(1) Electro convulsive therapy may be administered to a person (other than an involuntary patient or a person who is under the age of 16 years) if—"],[2,"(a) the person is capable of giving informed consent to the treatment and has given informed consent to the treatment, including a written consent in the form prescribed by the regulations, and"],[2,"(b) a certificate is given under this section by at least 2 medical practitioners, at least one of whom is a psychiatrist."],[1,"(2) A certificate under this section is a certificate in writing that, after considering the clinical condition and history of treatment of, and any appropriate alternative treatments for, the person, the medical practitioners are of the opinion that electro convulsive therapy is—"],[2,"(a) a reasonable and proper treatment to be administered to the person, and"],[2,"(b) necessary or desirable for the safety or welfare of the person."],[1,"(3) An authorised medical officer who is unsure whether a person is capable of giving informed consent may apply to the Tribunal for an ECT consent inquiry to determine whether the person is capable of giving informed consent and has given that consent."]],"url":"https://legislation.nsw.gov.au/view/html/inforce/current/act-2007-008#/sec.93"},{"n":"94","heading":"When electro convulsive therapy may be administered to involuntary patients or persons under 16","lines":[[1,"(1) Electro convulsive therapy may be administered to an involuntary patient or a person who is under the age of 16 years in accordance with an ECT determination made by the Tribunal at an ECT administration inquiry."],[1,"(2) An authorised medical officer may apply to the Tribunal for an ECT administration inquiry about an involuntary patient (other than a patient who is under the age of 16 years) if a certificate is given under this section by at least 2 medical practitioners, at least one of whom is a psychiatrist."],[1,"(2A) An authorised medical officer may apply to the Tribunal for an ECT administration inquiry about a person who is under the age of 16 years (including an involuntary patient) if a certificate is given under this section by at least 2 medical practitioners, at least one of whom is a psychiatrist with expertise in the treatment of children or adolescents."],[1,"(3) A certificate under this section is a certificate in writing that, after considering the clinical condition and history of treatment of, and any appropriate alternative treatments for, the patient, the medical practitioners are of the opinion that electro convulsive therapy is—"],[2,"(a) a reasonable and proper treatment to be administered to the patient, and"],[2,"(b) necessary or desirable for the safety or welfare of the patient."]],"url":"https://legislation.nsw.gov.au/view/html/inforce/current/act-2007-008#/sec.94"},{"n":"98","heading":"Definitions","lines":[[0,"In this Part—"],[1,"involuntary patient includes a forensic patient and a correctional patient."],[1,"special medical treatment means—"],[2,"(a) any treatment, procedure, operation or examination that is intended, or is reasonably likely, to have the effect of rendering permanently infertile the person on whom it is carried out, or"],[2,"(b) any other kind of treatment declared by the regulations to be special medical treatment for the purposes of this Part."],[1,"surgical operation means a surgical procedure, a series of related surgical operations or surgical procedures, and the administration of an anaesthetic for the purpose of medical investigation."]],"url":"https://legislation.nsw.gov.au/view/html/inforce/current/act-2007-008#/sec.98"},{"n":"99","heading":"Emergency surgery for involuntary patients","lines":[[1,"(1) An authorised medical officer or the Secretary may consent to the performance of a surgical operation on an involuntary patient (other than a forensic patient or correctional patient not suffering from a mental illness) if of the opinion that—"],[2,"(a) the patient is incapable of giving consent to the operation or is capable of giving consent but refuses to give that consent or neither gives nor refuses to give that consent, and"],[2,"(b) it is necessary, as a matter of urgency, to perform a surgical operation on the patient in order to save the patient’s life or to prevent serious damage to the patient’s health or to prevent the patient from suffering or continuing to suffer significant pain or distress."],[1,"(2) An authorised medical officer or the Secretary may consent to the performance of a surgical operation on a forensic patient or correctional patient not suffering from a mental illness if of the opinion that—"],[2,"(a) the patient is incapable of giving consent to the operation, and"],[2,"(b) it is necessary, as a matter of urgency, to perform a surgical operation on the patient in order to save the patient’s life or to prevent serious damage to the patient’s health or to prevent the patient from suffering or continuing to suffer significant pain or distress."],[1,"(3) The consent is to be in writing and signed by the person giving the consent."],[1,"(4) The authorised medical officer of the mental health facility in which the involuntary patient is detained must, as soon as practicable after the performance of a surgical operation consented to under this section, notify the Tribunal of the operation."]],"url":"https://legislation.nsw.gov.au/view/html/inforce/current/act-2007-008#/sec.99"},{"n":"100","heading":"Secretary may consent to surgery","lines":[[1,"(1) An authorised medical officer may apply to the Secretary for consent to the performance of a surgical operation on an involuntary patient."],[1,"(2) An application is to be made to the Secretary if a designated carer of the patient agrees, in writing, to the performance of the surgical operation."],[1,"(3) On an application, the Secretary may consent to the performance of a surgical operation on an involuntary patient if of the opinion that—"],[2,"(a) the patient is incapable of giving consent to the operation, and"],[2,"(b) it is desirable, having regard to the interests of the patient, to perform the surgical operation on the patient."],[1,"(4)"],[1,"(5) An application must be made not earlier than 14 days after notice of the proposed application is given under section 78, but may be made sooner if—"],[2,"(a) the authorised medical officer is of the opinion that the urgency of the circumstances requires an earlier determination of the matter, or"],[2,"(b) the person notified indicates that the person does not object."],[1,"(6) The consent is to be in writing and signed by the person giving the consent."]],"url":"https://legislation.nsw.gov.au/view/html/inforce/current/act-2007-008#/sec.100"},{"n":"101","heading":"Tribunal may consent to surgery","lines":[[1,"(1) An authorised medical officer of a mental health facility may apply to the Tribunal for consent to the performance of a surgical operation on an involuntary patient detained in the facility."],[1,"(2) An application is to be made to the Tribunal if none of the designated carers of the person agree, in writing, to the performance of the surgical operation."],[1,"(3) On an application, the Tribunal may consent to the performance of a surgical operation on an involuntary patient (other than a forensic patient or correctional patient not suffering from a mental illness) if the Tribunal is of the opinion that—"],[2,"(a) the patient is incapable of giving consent to the operation or is capable of giving consent but refuses to give that consent or neither gives nor refuses to give that consent, and"],[2,"(b) it is desirable, having regard to the interests of the patient, to perform the surgical operation on the patient."],[1,"(4) On an application, the Tribunal may consent to the performance of a surgical operation on a forensic patient or correctional patient not suffering from a mental illness if the Tribunal is of the opinion that—"],[2,"(a) the patient is incapable of giving consent to the operation, and"],[2,"(b) it is desirable, having regard to the interests of the patient, to perform the surgical operation on the patient."],[1,"(5) An application for consent must be made not earlier than 14 days after notice of the proposed application is given under section 78, but may be made sooner if—"],[2,"(a) the authorised medical officer is of the opinion that the urgency of the circumstances requires an earlier determination of the matter, or"],[2,"(b) the person notified indicates that the person does not object."]],"url":"https://legislation.nsw.gov.au/view/html/inforce/current/act-2007-008#/sec.101"},{"n":"102","heading":"Special medical treatment","lines":[[1,"(1) A person must not carry out special medical treatment on a patient otherwise than in accordance with this Part, unless the person is a medical practitioner and—"],[2,"(a) is of the opinion that it is necessary, as a matter of urgency, to carry out special medical treatment on the patient in order to save the patient’s life or to prevent serious damage to the patient’s health, or"],[2,"(b) consent to the treatment being carried out is given by the Tribunal in accordance with this Part."],[2,"Maximum penalty on indictment: imprisonment for 7 years."],[1,"(2) This section does not apply to a patient who is a child to whom section 175 of the Children and Young Persons (Care and Protection) Act 1998 applies."],[1,"Note: Note. This provision provides an offence in relation to carrying out special medical treatment on children."]],"url":"https://legislation.nsw.gov.au/view/html/inforce/current/act-2007-008#/sec.102"},{"n":"103","heading":"Tribunal may consent to special medical treatment","lines":[[1,"(1) An authorised medical officer of a mental health facility may apply to the Tribunal for consent to the carrying out of special medical treatment on an involuntary patient detained in the facility."],[1,"(2) On an application, the Tribunal may consent to the carrying out of special medical treatment on a patient (other than prescribed special medical treatment) if the Tribunal is satisfied that it is necessary to prevent serious damage to the health of the patient."],[1,"(3) The Tribunal may consent to the carrying out of prescribed special medical treatment if the Tribunal is satisfied that—"],[2,"(a) the treatment is the only or most appropriate way of treating the patient, and is manifestly in the best interests of the patient, and"],[2,"(b) in so far as the National Health and Medical Research Council has prescribed guidelines that are relevant to the carrying out of the treatment—those guidelines have been or will be complied with as regards the patient."],[1,"(4) The Tribunal must not consent to the carrying out of special medical treatment on a patient who is under the age of 16 years."],[1,"(5) An application for consent must be made not earlier than 14 days after notice of the proposed application is given under section 78, but may be made sooner if the authorised medical officer is of the opinion that the urgency of the circumstances requires an earlier determination of the matter or the person notified agrees."],[1,"(6) In this section—"],[2,"prescribed special medical treatment means special medical treatment referred to in paragraph (b) of the definition of special medical treatment in section 98."]],"url":"https://legislation.nsw.gov.au/view/html/inforce/current/act-2007-008#/sec.103"},{"n":"104","heading":"Effect of consents","lines":[[0,"A consent given under this Part has the same effect as if it were given by the patient and the patient had the capacity to consent or, in the case of a child under the age of 14 years or a person under guardianship, by the person having capacity to consent on the child’s or person’s behalf."]],"url":"https://legislation.nsw.gov.au/view/html/inforce/current/act-2007-008#/sec.104"},{"n":"190","heading":"Act does not limit or affect other powers","lines":[[1,"(1) Nothing in this Act or the Mental Health and Cognitive Impairment Forensic Provisions Act 2020 limits or affects any power conferred on a police officer or any other person by or under any other law with respect to stopping, searching or detaining a person (whether or not a patient) or taking any such person to any place."],[1,"(2) Nothing in this Act or the Mental Health and Cognitive Impairment Forensic Provisions Act 2020 prevents an authorised medical officer from taking any action that the officer thinks fit to protect a patient or person detained in a mental health facility, or any other person in a mental health facility, from serious physical harm."]],"url":"https://legislation.nsw.gov.au/view/html/inforce/current/act-2007-008#/sec.190"},{"n":"191","heading":"Liability of certain persons exercising functions under this Act or the Mental Health and Cognitive Impairment Forensic Provisions Act 2020","lines":[[1,"(1) Any police officer, health care professional or ambulance officer who, in good faith, exercises a function that is conferred or imposed on that person by or under this Act or the Mental Health and Cognitive Impairment Forensic Provisions Act 2020 is not personally liable for any injury or damage caused by the exercise of that function."],[1,"(1A) Without limiting subsection (1), any person who is a member of staff of the NSW Health Service who, in good faith—"],[2,"(a) exercises a function that is conferred or imposed on the person by or under this Act or the Mental Health and Cognitive Impairment Forensic Provisions Act 2020, or"],[2,"(b) assists a health care professional or ambulance officer who is exercising a function that is conferred or imposed on the health care professional or ambulance officer by or under this Act or the Mental Health and Cognitive Impairment Forensic Provisions Act 2020,"],[1,"is not personally liable for any injury or damage caused in exercising, or in assisting the health care professional or ambulance officer in exercising, any such function."],[1,"(2) Nothing in this section, or any other provision of this Act or the Mental Health and Cognitive Impairment Forensic Provisions Act 2020 or the regulations, relieves a medical practitioner or other person from liability in respect of carrying out medical treatment on a patient or other person to which the medical practitioner or person would have been subject had the treatment been carried out with the patient’s or other person’s consent."],[1,"(3) Nothing in this section affects any exclusion from liability provided by another provision of this Act or the Mental Health and Cognitive Impairment Forensic Provisions Act 2020 or any other law."],[1,"(4) In this section, health care professional means a registered health practitioner or a student within the meaning of the Health Practitioner Regulation National Law (NSW)."]],"url":"https://legislation.nsw.gov.au/view/html/inforce/current/act-2007-008#/sec.191"}]};
